#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BrowserCallerGrant {
    pub endpoint_ref: String,
    pub provider: String,
    pub account_ref: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BrowserCallerAuthorization {
    pub principal_ref: String,
    pub connector_id: String,
    pub grant_generation: i64,
    // Display-only platform_account labels live Edge-side; they never ride
    // the authorization wire and are not part of the runtime struct.
}

/// `<platform>-<email>` display label. The first `-` separates the platform
/// from the account, so the email may itself contain `-`.
pub(crate) fn normalize_platform_account(value: &str) -> Option<String> {
    let text = value.trim().to_ascii_lowercase();
    if text.len() < 6 || text.len() > 128 {
        return None;
    }
    let (platform, account) = text.split_once('-')?;
    if !is_platform_account_token(platform) || !is_platform_account_email(account) {
        return None;
    }
    Some(text)
}

fn is_platform_account_token(value: &str) -> bool {
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    first.is_ascii_lowercase()
        && value.len() <= 32
        && chars.all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit())
}

fn is_platform_account_email(value: &str) -> bool {
    let Some((local, domain)) = value.split_once('@') else {
        return false;
    };
    if local.is_empty()
        || !local.chars().all(|ch| {
            ch.is_ascii_lowercase()
                || ch.is_ascii_digit()
                || matches!(ch, '.' | '_' | '%' | '+' | '-')
        })
    {
        return false;
    }
    let Some((host, tld)) = domain.rsplit_once('.') else {
        return false;
    };
    !host.is_empty()
        && !host.starts_with(['.', '-'])
        && !host.ends_with(['.', '-'])
        && !host.contains("..")
        && host
            .chars()
            .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || matches!(ch, '.' | '-'))
        && (2..=24).contains(&tld.len())
        && tld.chars().all(|ch| ch.is_ascii_lowercase())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BrowserCallerSessionIdentity {
    pub provider: String,
    pub opaque_session_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PageAssistCallerGrant {
    pub endpoint_ref: String,
}

#[derive(Default)]
pub struct BrowserMutationAdmission {
    active_accounts: std::sync::Mutex<std::collections::HashSet<String>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BrowserMutationScope {
    endpoint_ref: String,
    provider: String,
    account_ref: String,
}

struct BrowserMutationPermit<'a> {
    admission: &'a BrowserMutationAdmission,
    key: String,
}

impl BrowserMutationAdmission {
    fn reserve<'a>(
        &'a self,
        scope: &BrowserMutationScope,
    ) -> Result<Option<BrowserMutationPermit<'a>>, String> {
        let key = format!(
            "{}\u{0}{}\u{0}{}",
            scope.endpoint_ref, scope.provider, scope.account_ref
        );
        let mut active = self
            .active_accounts
            .lock()
            .map_err(|_| "browser_mutation_admission_unavailable".to_owned())?;
        if !active.insert(key.clone()) {
            return Ok(None);
        }
        Ok(Some(BrowserMutationPermit {
            admission: self,
            key,
        }))
    }
}

impl Drop for BrowserMutationPermit<'_> {
    fn drop(&mut self) {
        if let Ok(mut active) = self.admission.active_accounts.lock() {
            active.remove(&self.key);
        }
    }
}

