    #[test]
    fn work_pickup_returns_latest_matching_state_or_empty_success() {
        use crate::state_store::work_journal::WorkState;
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        store
            .lock()
            .unwrap()
            .put_work_state(&WorkState {
                project_ref: "project-a".to_owned(),
                worktree: "/repo".to_owned(),
                handoff_md: "# Ready".to_owned(),
                through_event_id: 9,
                log_cursors_json: "{}".to_owned(),
                updated_at: 12,
            })
            .unwrap();
        let found = work_pickup_call(
            &store,
            &json!({"project_root": "/repo", "project_ref": "project-a"}),
            None,
        );
        assert_eq!(found["ok"], true);
        assert_eq!(found["handoff_md"], "# Ready");
        assert_eq!(found["through_event_id"], 9);
        assert_eq!(found["updated_at"], 12);
        // A legacy free-form handoff has no structured sections block.
        assert_eq!(found["sections"], Value::Null);

        let empty = work_pickup_call(&store, &json!({"worktree": "/other"}), None);
        assert_eq!(empty["ok"], true);
        assert_eq!(empty["handoff_md"], "");
        assert_eq!(empty["through_event_id"], 0);
        assert_eq!(empty["updated_at"], 0);

        for bad in [
            json!({"worktree": "/repo", "project_root": "/repo"}),
            json!({"nope": 1}),
            json!({"cwd": ""}),
            json!({"pane": 7}),
        ] {
            assert_eq!(
                work_pickup_call(&store, &bad, None)["code"],
                "work_pickup_params_invalid",
                "{bad}"
            );
        }
    }

    /// user pickup without selectors | Given recorded handoffs | When
    /// work.pickup is called with no worktree/project_root/cwd/pane | Then it
    /// lists the projects with handoffs instead of failing.
    #[test]
    fn work_pickup_without_params_lists_projects_with_handoffs() {
        use crate::state_store::work_journal::WorkState;
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        for (worktree, project_ref, handoff, updated_at) in [
            ("/a", "dir:/a", "# A", 3),
            ("/b", "git:example/b", "# B", 9),
            ("/empty", "dir:/empty", "   ", 7),
        ] {
            store
                .lock()
                .unwrap()
                .put_work_state(&WorkState {
                    project_ref: project_ref.to_owned(),
                    worktree: worktree.to_owned(),
                    handoff_md: handoff.to_owned(),
                    updated_at,
                    ..WorkState::default()
                })
                .unwrap();
        }
        let listed = work_pickup_call(&store, &json!({}), None);
        assert_eq!(listed["ok"], true);
        let projects = listed["projects"].as_array().unwrap();
        // Empty-handoff scopes stay out; newest first.
        assert_eq!(projects.len(), 2);
        assert_eq!(
            projects[0],
            json!({"worktree": "/b", "project_ref": "git:example/b", "updated_at": 9})
        );
        assert_eq!(
            projects[1],
            json!({"worktree": "/a", "project_ref": "dir:/a", "updated_at": 3})
        );
    }

    /// user pickup via caller cwd | Given a handoff under a managed Git root
    /// and a caller cwd inside it | When work.pickup passes only cwd | Then
    /// the project handoff resolves, with structured sections and the
    /// handoff-reference report.
    #[test]
    fn work_pickup_resolves_cwd_to_project_handoff() {
        use crate::state_store::work_journal::WorkState;
        use crate::work_compactor::{RelayItem, RelayMemory, render_handoff};
        use std::sync::{Arc, Mutex};

        let root = std::env::temp_dir().join(format!(
            "herdr-work-pickup-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::create_dir(root.join(".git")).unwrap();
        std::fs::write(root.join("AGENTS.md"), "see HANDOFF.md\n").unwrap();

        let memory = RelayMemory {
            goals: vec![RelayItem {
                id: "g1".to_owned(),
                text: "ship relay".to_owned(),
            }],
            current_state: "green".to_owned(),
            ..RelayMemory::default()
        };
        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        store
            .lock()
            .unwrap()
            .put_work_state(&WorkState {
                project_ref: "git:example/repo".to_owned(),
                worktree: root.to_string_lossy().into_owned(),
                handoff_md: render_handoff(&memory),
                through_event_id: 4,
                updated_at: 5,
                ..WorkState::default()
            })
            .unwrap();
        let snapshot = json!({
            "panes": [{
                "pane_id": "w1:p1",
                "workspace_id": "w1",
                "cwd": root.join("src").to_string_lossy()
            }],
            "agents": []
        });

        // cwd resolution through the topology project root.
        let by_cwd = work_pickup_call(
            &store,
            &json!({"cwd": root.join("src").to_string_lossy()}),
            Some(&snapshot),
        );
        assert_eq!(by_cwd["ok"], true);
        assert_eq!(by_cwd["through_event_id"], 4);
        assert!(by_cwd["handoff_md"].as_str().unwrap().contains("## 规则"));
        assert_eq!(by_cwd["sections"]["goals"][0]["text"], "ship relay");

        // pane resolution goes through the pane's live cwd the same way.
        let by_pane = work_pickup_call(&store, &json!({"pane": "w1:p1"}), Some(&snapshot));
        assert_eq!(by_pane["handoff_md"], by_cwd["handoff_md"]);

        // A cwd that resolves to no project and no recorded worktree is an
        // empty success, never an error.
        let unknown = work_pickup_call(
            &store,
            &json!({"cwd": "/definitely/nowhere"}),
            Some(&snapshot),
        );
        assert_eq!(unknown["ok"], true);
        assert_eq!(unknown["handoff_md"], "");
        std::fs::remove_dir_all(root).unwrap();
    }

    /// Accepted-text evidence a real content script now reports alongside the
    /// provider user-message identity. Applied fixtures must carry it because
    /// the runtime re-verifies the accepted provider text digest.
    fn accepted_text_and_body_evidence(text: &str, body: &str) -> Value {
        json!({
            "accepted_user_text_sha256": browser_sha256(text.trim()),
            "accepted_user_body_sha256": browser_sha256(body.trim()),
            "accepted_user_text_canonical_sha256": browser_sha256(
                &browser_readback_text_canonical(text)
            ),
            "accepted_user_body_canonical_sha256": browser_sha256(
                &browser_readback_text_canonical(body)
            ),
        })
    }

    fn accepted_text_evidence(message: &str) -> Value {
        accepted_text_and_body_evidence(message, message)
    }

    fn accepted_result(message: &str, accepted_ref: &str) -> Value {
        let mut value = accepted_text_evidence(message);
        value
            .as_object_mut()
            .unwrap()
            .insert("accepted_user_message_ref".to_owned(), json!(accepted_ref));
        value
    }

    fn semantic_test_server(body: &'static str) -> String {
        use std::io::{Read, Write};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut request = [0_u8; 16 * 1024];
            let _ = stream.read(&mut request);
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).unwrap();
        });
        format!("http://127.0.0.1:{}/v1", address.port())
    }

    fn semantic_test_server_sequence(bodies: Vec<&'static str>) -> String {
        use std::io::{Read, Write};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        std::thread::spawn(move || {
            for body in bodies {
                let (mut stream, _) = listener.accept().unwrap();
                let mut request = [0_u8; 16 * 1024];
                let _ = stream.read(&mut request);
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                stream.write_all(response.as_bytes()).unwrap();
            }
        });
        format!("http://127.0.0.1:{}/v1", address.port())
    }

    fn write_semantic_test_config(config_dir: &std::path::Path, route_name: &str, url: &str) {
        let path = config_dir.join("config.json");
        std::fs::write(
            &path,
            format!(
                r#"{{"semantic":{{"routes":[{{"name":"{route_name}","protocol":"decision","url":"{url}","model":"jev-test","api_key":"test"}}]}}}}"#
            ),
        )
        .unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).unwrap();
        }
    }

    #[test]
    fn initialize_uses_supported_requested_protocol() {
        let result = initialize_result(&json!({
            "params": {"protocolVersion": "2025-06-18"}
        }));
        assert_eq!(result["protocolVersion"], "2025-06-18");
        assert_eq!(result["serverInfo"]["name"], "herdr-mcp");
        assert_eq!(result["capabilities"]["tools"]["listChanged"], false);
        assert_eq!(result["_meta"]["herdr_contract_epoch"], 5);
        let instructions = result["instructions"].as_str().unwrap();
        assert!(instructions.contains("delivery, idempotency, and retryability evidence"));
        assert!(instructions.contains("current-state facts"));
        for forbidden in [
            " never ", " do not ", " prefer ", " should ", " must ", " call ", " load ", " use ",
        ] {
            assert!(
                !format!(" {} ", instructions.to_ascii_lowercase()).contains(forbidden),
                "directive wording leaked into MCP instructions: {instructions}"
            );
        }
    }

    #[test]
    fn unsupported_protocol_negotiates_to_sdk_wire() {
        let result = initialize_result(&json!({
            "params": {"protocolVersion": OPENAI_PROBE_PROTOCOL}
        }));
        assert_eq!(result["protocolVersion"], SDK_WIRE_PROTOCOL);
    }

    #[test]
    fn browser_source_turn_archive_resolution_is_durable_and_generation_fenced() {
        let mut store = StateStore::open(":memory:").unwrap();
        let now = 1_000_000_i64;
        let hash = browser_sha256("归档当前对话");
        let session_ref = format!("br_{}", "a".repeat(64));
        store
            .observe_browser_source_turn(&session_ref, 7, &hash, now)
            .unwrap();
        assert_eq!(
            store
                .resolve_browser_source_turn(&hash, now + 1_000)
                .unwrap(),
            (session_ref.clone(), 7)
        );

        // Beyond the retired 5-minute in-memory window but inside 24h retention.
        assert_eq!(
            store
                .resolve_browser_source_turn(&hash, now + 6 * 60 * 1000)
                .unwrap(),
            (session_ref.clone(), 7)
        );

        // Past the 24h retention window the turn is gone.
        assert_eq!(
            store
                .resolve_browser_source_turn(&hash, now + 24 * 60 * 60 * 1000 + 5_000)
                .unwrap_err(),
            "browser_current_turn_not_found"
        );

        // Two sessions sharing one digest fail closed instead of guessing.
        let shared = browser_sha256("共享的消息");
        let other_ref = format!("br_{}", "b".repeat(64));
        store
            .observe_browser_source_turn(&session_ref, 7, &shared, now)
            .unwrap();
        store
            .observe_browser_source_turn(&other_ref, 9, &shared, now + 1)
            .unwrap();
        assert_eq!(
            store
                .resolve_browser_source_turn(&shared, now + 2)
                .unwrap_err(),
            "browser_current_turn_ambiguous"
        );
    }

    #[test]
    fn browser_source_turn_archive_resolves_in_fresh_runtime_context() {
        use crate::state_store::{
            BrowserEndpointConsentInput, BrowserEndpointRegistrationInput,
            BrowserProviderObservationInput, BrowserResourceObservationInput,
        };

        let suffix = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "herdr-mcp-source-turn-fresh-runtime-{}-{suffix}.sqlite",
            std::process::id()
        ));
        let observed_at = browser_epoch_ms();
        let session_ref = {
            let mut guard = StateStore::open(&path).unwrap();
            let endpoint = guard
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "fresh-runtime-source-turn-profile-seed",
                    browser_family: "chrome",
                    extension_version: "0.1.91",
                    observed_at,
                })
                .unwrap();
            guard
                .observe_browser_provider(BrowserProviderObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    adapter_protocol_version: 1,
                    observation_generation: 7,
                    capabilities_json: "{\"operations\":[\"session.archive\"]}",
                    observed_at,
                })
                .unwrap();
            let account = guard
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "account",
                    parent_ref: None,
                    native_identity: "fresh-runtime-account",
                    display_label: None,
                    observation_generation: 7,
                    observed_at,
                })
                .unwrap();
            guard
                .set_browser_endpoint_consent(BrowserEndpointConsentInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    expected_revision: 0,
                    webchat_control_allowed: true,
                    tool_bridge_allowed: false,
                    tool_bridge_mutation_allowed: false,
                    observed_at,
                })
                .unwrap();
            let session = guard
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "session",
                    parent_ref: Some(&account.resource_ref),
                    native_identity: "fresh-runtime-session",
                    display_label: Some("Current"),
                    observation_generation: 7,
                    observed_at,
                })
                .unwrap();
            guard
                .upsert_browser_resource_locator(
                    &session.resource_ref,
                    "https://chatgpt.com/c/fresh-runtime-current",
                    7,
                    observed_at,
                )
                .unwrap();
            guard
                .observe_browser_source_turn(
                    &session.resource_ref,
                    7,
                    &source_turn_sha256("归档当前对话"),
                    observed_at,
                )
                .unwrap();
            session.resource_ref
        };

        // A fresh runtime context (reopened durable store, no in-memory
        // registry) resolves the archive from StateStore alone.
        let mut reopened = StateStore::open(&path).unwrap();
        let archive = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "归档当前对话",
                "idempotency_key": "archive-fresh-runtime"
            }),
            &[],
            None,
            None,
        )
        .unwrap()
        .unwrap();
        assert_eq!(archive["session_ref"], session_ref);
        assert_eq!(archive["expected_generation"], 7);

        // ChatGPT's opaque MCP session metadata is only a correlation key. The
        // first exact source-turn match may bind it, but only when the Connector
        // grant covers the resolved browser account.
        let initial_session = reopened.browser_resource(&session_ref).unwrap().unwrap();
        let initial_account_ref = initial_session.parent_ref.clone().unwrap();
        let grants = vec![BrowserCallerGrant {
            endpoint_ref: initial_session.endpoint_ref.clone(),
            provider: "chatgpt".to_owned(),
            account_ref: initial_account_ref.clone(),
        }];
        let authorization = BrowserCallerAuthorization {
            principal_ref: "connector:conn_current_chat_test".to_owned(),
            connector_id: "conn_current_chat_test".to_owned(),
            grant_generation: 1,
        };
        let caller_session = BrowserCallerSessionIdentity {
            provider: "chatgpt".to_owned(),
            opaque_session_id: "opaque-openai-session-current-chat".to_owned(),
        };
        let ungranted = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "归档当前对话",
                "idempotency_key": "archive-current-chat-without-grant"
            }),
            &[],
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap()
        .unwrap();
        assert_eq!(ungranted["session_ref"], session_ref);
        assert!(
            reopened
                .resolve_browser_caller_session(
                    &authorization.principal_ref,
                    "chatgpt",
                    &caller_session.opaque_session_id,
                )
                .unwrap()
                .is_none(),
            "opaque caller sessions must not become durable authority without a matching browser grant"
        );
        let bootstrap = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "归档当前对话",
                "idempotency_key": "archive-bind-current-chat"
            }),
            &grants,
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap()
        .unwrap();
        assert_eq!(bootstrap["session_ref"], session_ref);
        assert_eq!(
            reopened
                .resolve_browser_caller_session(
                    &authorization.principal_ref,
                    "chatgpt",
                    &caller_session.opaque_session_id,
                )
                .unwrap()
                .as_deref(),
            Some(session_ref.as_str())
        );

        let create_affinity = browser_create_caller_source_session_ref(
            &reopened,
            &json!({
                "endpoint_ref": initial_session.endpoint_ref,
                "provider": "chatgpt",
                "account_ref": initial_account_ref,
                "display_label": "Continuation",
                "message": "continue",
                "expected_generation": 7,
                "idempotency_key": "create-from-current-chat"
            }),
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap();
        assert_eq!(create_affinity.as_deref(), Some(session_ref.as_str()));
        let stale_create_affinity = browser_create_caller_source_session_ref(
            &reopened,
            &json!({
                "endpoint_ref": initial_session.endpoint_ref,
                "provider": "chatgpt",
                "account_ref": initial_account_ref,
                "display_label": "Continuation",
                "message": "continue",
                "expected_generation": 8,
                "idempotency_key": "create-from-stale-current-chat"
            }),
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap();
        assert_eq!(stale_create_affinity, None);

        // OpenAI may reuse the same opaque Connector caller session across
        // multiple ChatGPT conversations. A newer exact source-turn identity
        // must override the older correlation instead of routing the mutation
        // back into the previously bound conversation.
        let second_session = reopened
            .observe_browser_resource(BrowserResourceObservationInput {
                endpoint_ref: &initial_session.endpoint_ref,
                provider: "chatgpt",
                kind: "session",
                parent_ref: Some(&initial_account_ref),
                native_identity: "fresh-runtime-session-second",
                display_label: Some("Second"),
                observation_generation: 7,
                observed_at: observed_at + 1,
            })
            .unwrap();
        reopened
            .observe_browser_source_turn(
                &second_session.resource_ref,
                7,
                &source_turn_sha256("归档第二个对话"),
                observed_at + 1,
            )
            .unwrap();
        let rebound_to_second = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "归档第二个对话",
                "idempotency_key": "archive-rebind-current-chat-second"
            }),
            &grants,
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap()
        .unwrap();
        assert_eq!(
            rebound_to_second["session_ref"],
            second_session.resource_ref
        );
        assert_eq!(
            reopened
                .resolve_browser_caller_session(
                    &authorization.principal_ref,
                    "chatgpt",
                    &caller_session.opaque_session_id,
                )
                .unwrap()
                .as_deref(),
            Some(second_session.resource_ref.as_str()),
            "fresh exact source-turn evidence must safely retarget a reused opaque caller session"
        );

        let rebound_to_first = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "归档当前对话",
                "idempotency_key": "archive-rebind-current-chat-first"
            }),
            &grants,
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap()
        .unwrap();
        assert_eq!(rebound_to_first["session_ref"], session_ref);
        assert_eq!(
            reopened
                .resolve_browser_caller_session(
                    &authorization.principal_ref,
                    "chatgpt",
                    &caller_session.opaque_session_id,
                )
                .unwrap()
                .as_deref(),
            Some(session_ref.as_str())
        );

        // A generation drift observed after the source turn fails closed.
        let (endpoint_ref, account_ref) = {
            let session = reopened.browser_resource(&session_ref).unwrap().unwrap();
            (
                session.endpoint_ref.clone(),
                session.parent_ref.clone().unwrap(),
            )
        };
        reopened
            .observe_browser_provider(BrowserProviderObservationInput {
                endpoint_ref: &endpoint_ref,
                provider: "chatgpt",
                adapter_protocol_version: 1,
                observation_generation: 8,
                capabilities_json: "{\"operations\":[\"session.archive\"]}",
                observed_at,
            })
            .unwrap();
        let account = reopened
            .observe_browser_resource(BrowserResourceObservationInput {
                endpoint_ref: &endpoint_ref,
                provider: "chatgpt",
                kind: "account",
                parent_ref: None,
                native_identity: "fresh-runtime-account",
                display_label: None,
                observation_generation: 8,
                observed_at,
            })
            .unwrap();
        assert_eq!(account.resource_ref, account_ref);
        let drifted = reopened
            .observe_browser_resource(BrowserResourceObservationInput {
                endpoint_ref: &endpoint_ref,
                provider: "chatgpt",
                kind: "session",
                parent_ref: Some(&account_ref),
                native_identity: "fresh-runtime-session",
                display_label: Some("Current"),
                observation_generation: 8,
                observed_at,
            })
            .unwrap();
        assert_eq!(drifted.resource_ref, session_ref);
        let drift = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "归档当前对话",
                "idempotency_key": "archive-fresh-runtime-drift"
            }),
            &[],
            None,
            None,
        )
        .unwrap_err();
        assert_eq!(drift["code"], "browser_current_turn_stale");

        // Expire the source-turn row entirely. The previously bound caller
        // session is deliberately NOT a substitute for the exact current user
        // message: after an account/Profile change that binding can name another
        // conversation, so the archive target must stay unresolved instead of
        // mutating the wrong session.
        assert_eq!(
            reopened
                .resolve_browser_source_turn(
                    &source_turn_sha256("归档当前对话"),
                    observed_at + 24 * 60 * 60 * 1000 + 5_000,
                )
                .unwrap_err(),
            "browser_current_turn_not_found"
        );
        let binding_before = reopened
            .resolve_browser_caller_session(
                &authorization.principal_ref,
                "chatgpt",
                &caller_session.opaque_session_id,
            )
            .unwrap();
        let unresolved = browser_session_archive_params_from_current_turn(
            &mut reopened,
            &json!({
                "current_user_message": "这条消息没有 source-turn 记录",
                "idempotency_key": "archive-bound-after-source-expiry"
            }),
            &grants,
            Some(&authorization),
            Some(&caller_session),
        )
        .unwrap_err();
        assert_eq!(unresolved["code"], "browser_current_turn_not_found");
        assert_eq!(
            reopened
                .resolve_browser_caller_session(
                    &authorization.principal_ref,
                    "chatgpt",
                    &caller_session.opaque_session_id,
                )
                .unwrap(),
            binding_before,
            "an unresolved current turn must not rebind or reuse the stale caller session"
        );
        drop(reopened);
        std::fs::remove_file(&path).ok();
        std::fs::remove_file(path.with_extension("sqlite-wal")).ok();
        std::fs::remove_file(path.with_extension("sqlite-shm")).ok();
    }

    /// The Rust half of the JS<->Rust acceptance-digest parity contract. The
    /// extension reports these digests and this runtime re-verifies them, so a
    /// divergent trim or canonicalization silently turns an accepted submit into
    /// a permanent `uncertain`. `tests/browser-acceptance-digest-parity.test.mjs`
    /// hashes the same fixture with the shipped extension helpers.
    #[test]
    fn browser_acceptance_digest_parity_with_extension_fixture() {
        let fixture: Value = serde_json::from_str(include_str!(
            "../../../tests/fixtures/browser-acceptance-digest-parity.json"
        ))
        .unwrap();
        assert_eq!(fixture["schema_version"], 1);
        let cases = fixture["cases"].as_array().unwrap();
        assert!(
            cases.len() >= 10,
            "the shared fixture must pin a real whitespace matrix"
        );
        for case in cases {
            let name = case["name"].as_str().unwrap();
            let text = case["text"].as_str().unwrap();
            assert_eq!(
                browser_sha256(text.trim()),
                case["trimmed_sha256"].as_str().unwrap(),
                "{name}: trimmed digest must match the shared extension contract"
            );
            assert_eq!(
                browser_sha256(&browser_readback_text_canonical(text)),
                case["canonical_sha256"].as_str().unwrap(),
                "{name}: canonical digest must match the shared extension contract"
            );
        }
        // The two Unicode boundaries where the two languages historically
        // diverged: Rust `str::trim()` keeps U+FEFF (not White_Space) and strips
        // U+0085 (White_Space), the opposite of JS `String.prototype.trim()`.
        assert_ne!(
            browser_sha256("one two"),
            browser_sha256("\u{feff}one two".trim())
        );
        assert_eq!(
            browser_sha256("one two"),
            browser_sha256("\u{0085}one two".trim())
        );
        assert_eq!(
            browser_sha256(&browser_readback_text_canonical("one\u{0085}two")),
            browser_sha256("one two")
        );
    }

