    #[test]
    fn continuity_search_requires_confirmation_without_stable_identity() {
        use crate::state_store::{
            BrowserEndpointRegistrationInput, BrowserProviderObservationInput,
            BrowserResourceObservationInput, ContinuityTurnInput, WorkMemoryBindingInput,
        };
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        {
            let mut guard = store.lock().unwrap();
            for (
                continuity_id,
                conversation_id,
                workspace_id,
                project_id,
                title,
                message_id,
                text,
                observed_at,
            ) in [
                (
                    "hc:alpha",
                    "conv-a",
                    "w19",
                    "g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                    "Alpha release",
                    "msg-a",
                    "continue v0.4.2 release work",
                    100,
                ),
                (
                    "hc:beta",
                    "conv-b",
                    "w20",
                    "project-b",
                    "Beta provider",
                    "msg-b",
                    "continue provider work",
                    200,
                ),
            ] {
                guard
                    .append_continuity_turn(ContinuityTurnInput {
                        continuity_id,
                        conversation_id,
                        workspace_id: Some(workspace_id),
                        project_id: Some(project_id),
                        title: Some(title),
                        message_id,
                        role: "user",
                        text,
                        fingerprint: None,
                        observed_at,
                    })
                    .unwrap();
            }
            guard
                .bind_work_memory(WorkMemoryBindingInput {
                    continuity_id: "hc:alpha",
                    project_ref: "project:herdr-mcp",
                    repo_id: "github.com/whshang/herdr-mcp",
                    work_chain_id: "wc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                    provider: "chatgpt",
                    account_ref: Some("account-a"),
                    space_ref: Some("project-a"),
                    session_ref: "br_session_alpha",
                    bound_at: 110,
                })
                .unwrap();
        }

        let bare = continuity_call(&store, "continuity.search", &json!({}));
        assert_eq!(bare["ok"], true);
        assert_eq!(bare["resolution"], "confirmation_required");
        assert_eq!(bare["auto_resume_safe"], false);
        assert_eq!(bare["confirmation_required"], true);
        assert_eq!(bare["candidates"].as_array().unwrap().len(), 2);
        assert!(
            bare["instruction"]
                .as_str()
                .unwrap()
                .contains("Do not choose by recency")
        );

        let exact = continuity_call(&store, "continuity.search", &json!({"workspace_id": "w19"}));
        assert_eq!(exact["resolution"], "unique_exact");
        assert_eq!(exact["auto_resume_safe"], true);
        assert_eq!(exact["confirmation_required"], false);
        assert_eq!(exact["candidates"][0]["continuity_id"], "hc:alpha");
        assert_eq!(exact["candidates"][0]["match_reasons"][0], "workspace_id");

        let url_exact = continuity_call(
            &store,
            "continuity.search",
            &json!({
                "conversation_url": "https://chatgpt.com/g/g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-project/c/conv-a?foo=bar#tail"
            }),
        );
        assert_eq!(url_exact["resolution"], "unique_exact");
        assert_eq!(url_exact["auto_resume_safe"], true);
        assert_eq!(url_exact["candidates"][0]["continuity_id"], "hc:alpha");

        let resumed_url = continuity_call(
            &store,
            "continuity.resume",
            &json!({"conversation_url": "https://chatgpt.com/g/g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-project/c/conv-a"}),
        );
        assert_eq!(resumed_url["ok"], true);
        assert_eq!(resumed_url["continuity_id"], "hc:alpha");

        let resumed_identity = continuity_call(
            &store,
            "continuity.resume",
            &json!({
                "conversation_id": "conv-a",
                "project_id": "g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
            }),
        );
        assert_eq!(resumed_identity["ok"], true);
        assert_eq!(resumed_identity["continuity_id"], "hc:alpha");

        let resumed_identity_project = continuity_call(
            &store,
            "continuity.resume",
            &json!({
                "conversation_id": "unseen-conv",
                "project_id": "g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
            }),
        );
        assert_eq!(resumed_identity_project["ok"], false);
        assert_eq!(resumed_identity_project["code"], "continuity_not_found");

        let mixed_resume = continuity_call(
            &store,
            "continuity.resume",
            &json!({"continuity_id": "hc:alpha", "conversation_id": "conv-a"}),
        );
        assert_eq!(mixed_resume["ok"], false);
        assert_eq!(mixed_resume["code"], "continuity_resume_params_invalid");

        let empty_resume = continuity_call(&store, "continuity.resume", &json!({}));
        assert_eq!(empty_resume["ok"], false);
        assert_eq!(empty_resume["code"], "continuity_id_or_url_required");

        let resumed_project = continuity_call(
            &store,
            "continuity.resume",
            &json!({"conversation_url": "https://chatgpt.com/g/g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-project/c/unseen-conv"}),
        );
        assert_eq!(resumed_project["ok"], false);
        assert_eq!(resumed_project["code"], "continuity_not_found");

        let text_only = continuity_call(&store, "continuity.search", &json!({"query": "v0.4.2"}));
        assert_eq!(text_only["candidates"].as_array().unwrap().len(), 1);
        assert_eq!(text_only["resolution"], "confirmation_required");
        assert_eq!(text_only["auto_resume_safe"], false);

        let repo_scoped = continuity_call(
            &store,
            "continuity.search",
            &json!({"repo_id": "github.com/whshang/herdr-mcp"}),
        );
        assert_eq!(repo_scoped["candidates"].as_array().unwrap().len(), 1);
        assert_eq!(repo_scoped["candidates"][0]["continuity_id"], "hc:alpha");
        assert_eq!(repo_scoped["candidates"][0]["repo_scope"], "exact");
        assert_eq!(repo_scoped["candidates"][0]["match_reasons"][0], "repo_id");
        assert_eq!(repo_scoped["resolution"], "confirmation_required");
        assert_eq!(repo_scoped["auto_resume_safe"], false);
        assert_eq!(
            repo_scoped["candidates"][0]["work_memory"]["project_ref"],
            "project:herdr-mcp"
        );
        assert_eq!(
            repo_scoped["candidates"][0]["work_memory"]["repo_id"],
            "github.com/whshang/herdr-mcp"
        );
        assert_eq!(
            repo_scoped["candidates"][0]["work_memory"]["work_chain_id"],
            "wc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
        );

        let legacy_repo_scoped = continuity_call(
            &store,
            "continuity.search",
            &json!({
                "repo_id": "github.com/whshang/herdr-mcp",
                "query": "provider"
            }),
        );
        assert_eq!(
            legacy_repo_scoped["candidates"].as_array().unwrap().len(),
            1
        );
        assert_eq!(
            legacy_repo_scoped["candidates"][0]["continuity_id"],
            "hc:beta"
        );
        assert_eq!(
            legacy_repo_scoped["candidates"][0]["repo_scope"],
            "legacy_unbound"
        );
        assert_eq!(
            legacy_repo_scoped["candidates"][0]["work_memory"],
            Value::Null
        );
        assert_eq!(legacy_repo_scoped["resolution"], "confirmation_required");
        assert_eq!(legacy_repo_scoped["auto_resume_safe"], false);
        assert_eq!(legacy_repo_scoped["confirmation_required"], true);
        assert!(
            legacy_repo_scoped["instruction"]
                .as_str()
                .unwrap()
                .contains("legacy repo-unbound")
        );
        let legacy_reasons = legacy_repo_scoped["candidates"][0]["match_reasons"]
            .as_array()
            .unwrap();
        assert!(
            legacy_reasons
                .iter()
                .any(|value| value == "legacy_repo_unbound")
        );
        assert!(legacy_reasons.iter().any(|value| value == "query"));
        assert!(!legacy_reasons.iter().any(|value| value == "repo_id"));

        {
            let mut guard = store.lock().unwrap();
            guard
                .append_continuity_turn(ContinuityTurnInput {
                    continuity_id: "hc:gamma",
                    conversation_id: "conv-c",
                    workspace_id: Some("w19"),
                    project_id: Some("g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
                    title: Some("Gamma release"),
                    message_id: "msg-c",
                    role: "user",
                    text: "another release chain",
                    fingerprint: None,
                    observed_at: 300,
                })
                .unwrap();
        }

        let ambiguous =
            continuity_call(&store, "continuity.search", &json!({"workspace_id": "w19"}));
        assert_eq!(ambiguous["resolution"], "confirmation_required");
        assert_eq!(ambiguous["auto_resume_safe"], false);
        assert_eq!(ambiguous["candidates"].as_array().unwrap().len(), 2);

        let ambiguous_identity_resume = continuity_call(
            &store,
            "continuity.resume",
            &json!({
                "conversation_id": "missing-conv",
                "project_id": "g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
            }),
        );
        assert_eq!(ambiguous_identity_resume["ok"], false);
        assert_eq!(ambiguous_identity_resume["code"], "continuity_ambiguous");

        let ambiguous_url_search = continuity_call(
            &store,
            "continuity.search",
            &json!({
                "conversation_url": "https://chatgpt.com/g/g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-project/c/missing-conv"
            }),
        );
        assert_eq!(ambiguous_url_search["resolution"], "confirmation_required");
        assert_eq!(ambiguous_url_search["auto_resume_safe"], false);
        assert_eq!(
            ambiguous_url_search["candidates"].as_array().unwrap().len(),
            2
        );
        assert!(
            ambiguous_url_search["candidates"]
                .as_array()
                .unwrap()
                .iter()
                .all(|candidate| candidate["match_reasons"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|reason| reason == "project_id_fallback"))
        );

        let identity_plus_text = continuity_call(
            &store,
            "continuity.search",
            &json!({"workspace_id": "w19", "query": "v0.4.2"}),
        );
        assert_eq!(
            identity_plus_text["candidates"].as_array().unwrap().len(),
            1
        );
        assert_eq!(
            identity_plus_text["candidates"][0]["continuity_id"],
            "hc:alpha"
        );
        assert_eq!(identity_plus_text["resolution"], "confirmation_required");
        assert_eq!(identity_plus_text["auto_resume_safe"], false);

        let invalid = continuity_call(
            &store,
            "continuity.search",
            &json!({"workspace_id": 19, "limit": 99}),
        );
        assert_eq!(invalid["ok"], false);
        assert_eq!(invalid["code"], "continuity_search_params_invalid");

        // A single canonical URL observed by two distinct browser sessions is
        // ambiguous even when one observation is newer. Resuming from the URL must
        // surface continuity_ambiguous, never a generic read failure or a recency pick.
        {
            let mut guard = store.lock().unwrap();
            for (seed, identity, observed_at) in [
                ("url-ambig-endpoint-a", "conversation-ambig-a", 100),
                ("url-ambig-endpoint-b", "conversation-ambig-b", 900),
            ] {
                let endpoint = guard
                    .register_browser_endpoint(BrowserEndpointRegistrationInput {
                        device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                        profile_seed: seed,
                        browser_family: "ego",
                        extension_version: "0.1.91",
                        observed_at,
                    })
                    .unwrap();
                let generation = if observed_at < 500 { 7 } else { 8 };
                guard
                    .observe_browser_provider(BrowserProviderObservationInput {
                        endpoint_ref: &endpoint.endpoint_ref,
                        provider: "chatgpt",
                        adapter_protocol_version: 1,
                        observation_generation: generation,
                        capabilities_json: r#"{"operations":["session.inspect"]}"#,
                        observed_at,
                    })
                    .unwrap();
                let account_identity = format!("{identity}-account");
                let account = guard
                    .observe_browser_resource(BrowserResourceObservationInput {
                        endpoint_ref: &endpoint.endpoint_ref,
                        provider: "chatgpt",
                        kind: "account",
                        parent_ref: None,
                        native_identity: &account_identity,
                        display_label: None,
                        observation_generation: generation,
                        observed_at,
                    })
                    .unwrap();
                let session = guard
                    .observe_browser_resource(BrowserResourceObservationInput {
                        endpoint_ref: &endpoint.endpoint_ref,
                        provider: "chatgpt",
                        kind: "session",
                        parent_ref: Some(&account.resource_ref),
                        native_identity: identity,
                        display_label: None,
                        observation_generation: generation,
                        observed_at,
                    })
                    .unwrap();
                guard
                    .upsert_browser_resource_locator(
                        &session.resource_ref,
                        "https://chatgpt.com/c/ambiguous-distinct-url",
                        generation,
                        observed_at,
                    )
                    .unwrap();
            }
        }
        let ambiguous_url_resume = continuity_call(
            &store,
            "continuity.resume",
            &json!({"conversation_url": "https://chatgpt.com/c/ambiguous-distinct-url"}),
        );
        assert_eq!(ambiguous_url_resume["ok"], false);
        assert_eq!(ambiguous_url_resume["code"], "continuity_ambiguous");
    }

    #[test]
    fn work_memory_private_methods_share_state_store_and_provider_qualify_messages() {
        use std::sync::{Arc, Mutex};

        let _env_guard = crate::test_env::lock();
        let previous_config = std::env::var_os("HERDR_MCP_CONFIG_DIR");
        let config_dir = std::env::temp_dir().join(format!(
            "herdr-work-memory-private-empty-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&config_dir);
        std::fs::create_dir_all(&config_dir).unwrap();
        unsafe {
            std::env::set_var("HERDR_MCP_CONFIG_DIR", &config_dir);
        }

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let mut message_ids = Vec::new();
        for (provider, account_ref) in [("chatgpt", "account-a"), ("gemini", "account-b")] {
            let bound = work_memory_call(
                &store,
                "work_memory.bind",
                &json!({
                    "continuity_id": "wm:mcp",
                    "project_ref": "project:herdr-mcp",
                    "repo_id": "github.com/whshang/herdr-mcp",
                    "work_chain_id": "wc_cccccccccccccccccccccccccccccccc",
                    "provider": provider,
                    "account_ref": account_ref,
                    "space_ref": "project-space",
                    "session_ref": "same-session",
                    "bound_at": 100,
                }),
            );
            assert_eq!(bound["ok"], true);

            let appended = work_memory_call(
                &store,
                "work_memory.append_turn",
                &json!({
                    "continuity_id": "wm:mcp",
                    "provider": provider,
                    "account_ref": account_ref,
                    "space_ref": "project-space",
                    "session_ref": "same-session",
                    "provider_message_ref": "same-message",
                    "role": if provider == "chatgpt" { "user" } else { "assistant" },
                    "text": format!("{provider} work memory turn\n\n```text\nline\t2\n```"),
                    "observed_at": if provider == "chatgpt" { 110 } else { 111 },
                }),
            );
            assert_eq!(appended["ok"], true);
            assert_eq!(appended["inserted"], true);
            message_ids.push(appended["message_id"].as_str().unwrap().to_owned());
        }
        assert_ne!(message_ids[0], message_ids[1]);

        let evidence = work_memory_call(
            &store,
            "work_memory.append_evidence",
            &json!({
                "continuity_id": "wm:mcp",
                "kind": "result",
                "content": "provider-neutral durable result\n\n```text\nexit\t0\n```",
                "provider": "gemini",
                "account_ref": "account-b",
                "space_ref": "project-space",
                "session_ref": "same-session",
                "portable_source": {
                    "repo_id": "github.com/whshang/herdr-mcp",
                    "commit_sha": "0123456789abcdef0123456789abcdef01234567",
                    "repo_relative_path": "crates/herdr-mcp/src/mcp.rs",
                    "line_start": 1,
                    "line_end": 10
                },
                "created_at": 112,
            }),
        );
        assert_eq!(evidence["ok"], true);
        assert!(evidence["evidence_id"].as_str().unwrap().starts_with("ev_"));
        assert_eq!(
            evidence["portable_evidence_ref"]["repo_relative_path"],
            "crates/herdr-mcp/src/mcp.rs"
        );

        let missing_anchor = work_memory_call(
            &store,
            "work_memory.checkpoint.put",
            &json!({
                "continuity_id": "wm:mcp",
                "expected_checkpoint_revision": 0,
                "summary": "must fail before StateStore",
                "checkpoint_json": "{\"goal\":\"missing-anchor\"}",
                "created_at": 117,
            }),
        );
        assert_eq!(missing_anchor["ok"], false);
        assert_eq!(
            missing_anchor["code"],
            "work_memory_checkpoint_anchor_required"
        );

        let message_only = work_memory_call(
            &store,
            "work_memory.checkpoint.put",
            &json!({
                "continuity_id": "wm:mcp",
                "expected_checkpoint_revision": 0,
                "summary": "message anchored",
                "checkpoint_json": "{\"goal\":\"message-only\"}",
                "through_message_id": message_ids[1],
                "created_at": 118,
            }),
        );
        assert_eq!(message_only["ok"], true);
        assert_eq!(message_only["checkpoint"]["revision"], 1);

        let evidence_only = work_memory_call(
            &store,
            "work_memory.checkpoint.put",
            &json!({
                "continuity_id": "wm:mcp",
                "expected_checkpoint_revision": 1,
                "summary": "evidence anchored",
                "checkpoint_json": "{\"goal\":\"evidence-only\"}",
                "through_evidence_id": evidence["evidence_id"],
                "created_at": 119,
            }),
        );
        assert_eq!(evidence_only["ok"], true);
        assert_eq!(evidence_only["checkpoint"]["revision"], 2);

        let checkpoint = work_memory_call(
            &store,
            "work_memory.checkpoint.put",
            &json!({
                "continuity_id": "wm:mcp",
                "expected_checkpoint_revision": 2,
                "summary": "MCP checkpoint\nready for handoff",
                "checkpoint_json": "{\n\t\"goal\": \"alpha2\"\n}",
                "through_message_id": message_ids[1],
                "through_evidence_id": evidence["evidence_id"],
                "created_at": 120,
            }),
        );
        assert_eq!(checkpoint["ok"], true);
        assert_eq!(checkpoint["checkpoint"]["revision"], 3);
        assert_eq!(checkpoint["checkpoint"]["verified"], true);

        let resumed = work_memory_call(
            &store,
            "work_memory.resume",
            &json!({
                "project_ref": "project:herdr-mcp",
                "repo_id": "github.com/whshang/herdr-mcp",
                "work_chain_id": "wc_cccccccccccccccccccccccccccccccc",
                "max_turns": 8
            }),
        );
        assert_eq!(resumed["ok"], true);
        assert_eq!(
            resumed["work_chain_id"],
            "wc_cccccccccccccccccccccccccccccccc"
        );
        assert_eq!(resumed["turns"].as_array().unwrap().len(), 2);
        assert_eq!(resumed["turns"][0]["provider"], "chatgpt");
        assert_eq!(resumed["turns"][1]["provider"], "gemini");
        assert_eq!(resumed["coverage"]["result_completeness"], "complete");
        assert_eq!(resumed["coverage"]["source_verification"], "unverified");
        assert_eq!(resumed["coverage"]["display_truncated"], false);
        assert!(
            resumed["coverage"]["limitations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|value| value == "source_revision_unverified")
        );

        let tight_resume = work_memory_call(
            &store,
            "work_memory.resume",
            &json!({
                "project_ref": "project:herdr-mcp",
                "repo_id": "github.com/whshang/herdr-mcp",
                "work_chain_id": "wc_cccccccccccccccccccccccccccccccc",
                "max_turns": 1
            }),
        );
        assert_eq!(tight_resume["ok"], true);
        assert_eq!(tight_resume["turns"].as_array().unwrap().len(), 1);
        assert_eq!(tight_resume["coverage"]["result_completeness"], "complete");
        assert_eq!(tight_resume["coverage"]["display_truncated"], true);
        assert!(
            tight_resume["coverage"]["limitations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|value| value == "display_page_truncated")
        );

        let searched = work_memory_call(
            &store,
            "work_memory.search",
            &json!({
                "project_ref": "project:herdr-mcp",
                "repo_id": "github.com/whshang/herdr-mcp",
                "work_chain_id": "wc_cccccccccccccccccccccccccccccccc",
                "query": "durable result"
            }),
        );
        assert_eq!(searched["ok"], true);
        assert_eq!(searched["hits"].as_array().unwrap().len(), 1);
        assert_eq!(searched["hits"][0]["source_kind"], "evidence");
        assert_eq!(searched["semantic_ranking"]["used"], false);
        assert_eq!(searched["coverage"]["result_completeness"], "complete");
        assert_eq!(searched["coverage"]["source_verification"], "unverified");

        let _ = std::fs::remove_dir_all(&config_dir);
        unsafe {
            match previous_config {
                Some(value) => std::env::set_var("HERDR_MCP_CONFIG_DIR", value),
                None => std::env::remove_var("HERDR_MCP_CONFIG_DIR"),
            }
        }
    }

    #[test]
    fn work_memory_evidence_sufficient_is_live_advisory_across_semantic_states() {
        let _guard = crate::test_env::lock();
        let previous_config = std::env::var_os("HERDR_MCP_CONFIG_DIR");
        let config_dir =
            std::env::temp_dir().join(format!("herdr-work-memory-semantic-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&config_dir);
        std::fs::create_dir_all(&config_dir).unwrap();
        unsafe {
            std::env::set_var("HERDR_MCP_CONFIG_DIR", &config_dir);
        }
        let hits = vec![
            WorkMemorySearchHit {
                source_kind: "evidence".to_owned(),
                source_id: "ev_strict".to_owned(),
                excerpt: "The release gate was discussed.".to_owned(),
                strict_match: true,
            },
            WorkMemorySearchHit {
                source_kind: "evidence".to_owned(),
                source_id: "ev_relaxed".to_owned(),
                excerpt: "The gate passed after rollout.".to_owned(),
                strict_match: false,
            },
        ];

        let no_config = work_memory_semantic_ranking(
            &SemanticService::from_config(),
            "Did the release gate pass?",
            &hits,
        );
        assert_eq!(no_config["used"], false);
        assert_eq!(no_config["advisory_only"], true);
        assert_eq!(no_config["reason"], "not_configured");

        let semantic_url = semantic_test_server(
            r#"{"model":"jev-test","answers":{"hit_0":{"type":"noul","noul":0.20},"hit_1":{"type":"noul","noul":0.93},"evidence_sufficient":{"type":"noul","noul":0.87}}}"#,
        );
        write_semantic_test_config(&config_dir, "work-memory-evidence", &semantic_url);
        let configured = work_memory_semantic_ranking(
            &SemanticService::from_config(),
            "Did the release gate pass?",
            &hits,
        );
        assert_eq!(configured["used"], true);
        assert_eq!(configured["advisory_only"], true);
        assert_eq!(configured["ranked"][0]["source_id"], "ev_relaxed");
        assert_eq!(configured["ranked"][0]["match_kind"], "relaxed");
        assert_eq!(
            configured["ranked"][0]["excerpt"],
            "The gate passed after rollout."
        );
        assert_eq!(configured["relaxed_candidate_count"], 1);
        assert_eq!(configured["evidence_sufficient"], 0.87);
        assert_eq!(configured["preserves_hit_order"], true);
        assert_eq!(configured["authority"], "advisory_only");

        write_semantic_test_config(&config_dir, "work-memory-evidence", "http://127.0.0.1:1/v1");
        let provider_error = work_memory_semantic_ranking(
            &SemanticService::from_config(),
            "Did the release gate pass?",
            &hits,
        );
        assert_eq!(provider_error["used"], false);
        assert_eq!(provider_error["advisory_only"], true);
        assert_ne!(provider_error["reason"], "not_configured");

        let _ = std::fs::remove_dir_all(&config_dir);
        unsafe {
            match previous_config {
                Some(value) => std::env::set_var("HERDR_MCP_CONFIG_DIR", value),
                None => std::env::remove_var("HERDR_MCP_CONFIG_DIR"),
            }
        }
    }

    #[test]
    fn work_memory_search_cursor_freezes_boundary_and_rejects_tampering() {
        use std::sync::{Arc, Mutex};

        let _env_guard = crate::test_env::lock();
        let previous_config = std::env::var_os("HERDR_MCP_CONFIG_DIR");
        let config_dir = std::env::temp_dir().join(format!(
            "herdr-work-memory-cursor-empty-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&config_dir);
        std::fs::create_dir_all(&config_dir).unwrap();
        unsafe {
            std::env::set_var("HERDR_MCP_CONFIG_DIR", &config_dir);
        }

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let bound = work_memory_call(
            &store,
            "work_memory.bind",
            &json!({
                "continuity_id": "wm:cursor",
                "project_ref": "project:cursor",
                "repo_id": "github.com/whshang/herdr-mcp",
                "work_chain_id": "wc_eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
                "provider": "chatgpt",
                "session_ref": "cursor-session",
                "bound_at": 1,
            }),
        );
        assert_eq!(bound["ok"], true);

        for index in 1..=3 {
            let appended = work_memory_call(
                &store,
                "work_memory.append_evidence",
                &json!({
                    "continuity_id": "wm:cursor",
                    "kind": "result",
                    "content": format!("stable-cursor-keyword evidence-{index}"),
                    "created_at": 10 + index,
                }),
            );
            assert_eq!(appended["ok"], true);
        }

        let first = work_memory_call(
            &store,
            "work_memory.search",
            &json!({
                "project_ref": "project:cursor",
                "repo_id": "github.com/whshang/herdr-mcp",
                "work_chain_id": "wc_eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
                "query": "stable-cursor-keyword",
                "limit": 2
            }),
        );
        assert_eq!(first["ok"], true);
        assert_eq!(first["hits"].as_array().unwrap().len(), 2);
        assert_eq!(first["semantic_ranking"]["used"], false);
        assert_eq!(first["coverage"]["result_completeness"], "complete");
        assert_eq!(first["coverage"]["display_truncated"], true);
        let cursor = first["cursor"].as_str().unwrap().to_owned();

        let appended_later = work_memory_call(
            &store,
            "work_memory.append_evidence",
            &json!({
                "continuity_id": "wm:cursor",
                "kind": "result",
                "content": "stable-cursor-keyword evidence-4-later",
                "created_at": 20,
            }),
        );
        assert_eq!(appended_later["ok"], true);

        let continued = work_memory_call(&store, "work_memory.search", &json!({"cursor": cursor}));
        assert_eq!(continued["ok"], true);
        assert_eq!(continued["hits"].as_array().unwrap().len(), 1);
        assert!(
            continued["hits"][0]["excerpt"]
                .as_str()
                .unwrap()
                .contains("evidence-1")
        );
        assert!(!continued.to_string().contains("evidence-4-later"));
        assert!(continued["cursor"].is_null());

        let replay = work_memory_call(
            &store,
            "work_memory.search",
            &json!({"cursor": first["cursor"]}),
        );
        let mut replay_authoritative = replay.clone();
        let mut continued_authoritative = continued.clone();
        replay_authoritative
            .as_object_mut()
            .unwrap()
            .remove("semantic_ranking");
        continued_authoritative
            .as_object_mut()
            .unwrap()
            .remove("semantic_ranking");
        assert_eq!(replay_authoritative, continued_authoritative);

        let fresh = work_memory_call(
            &store,
            "work_memory.search",
            &json!({
                "project_ref": "project:cursor",
                "repo_id": "github.com/whshang/herdr-mcp",
                "work_chain_id": "wc_eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
                "query": "stable-cursor-keyword",
                "limit": 1
            }),
        );
        assert_eq!(fresh["ok"], true);
        assert!(
            fresh["hits"][0]["excerpt"]
                .as_str()
                .unwrap()
                .contains("evidence-4-later")
        );

        let conflict = work_memory_call(
            &store,
            "work_memory.search",
            &json!({"cursor": first["cursor"], "limit": 1}),
        );
        assert_eq!(conflict["code"], "work_memory_cursor_conflict");

        let mut tampered = first["cursor"].as_str().unwrap().to_owned();
        let last = tampered.pop().unwrap();
        tampered.push(if last == '0' { '1' } else { '0' });
        let tampered_result =
            work_memory_call(&store, "work_memory.search", &json!({"cursor": tampered}));
        assert_eq!(tampered_result["code"], "work_memory_cursor_invalid");

        let _ = std::fs::remove_dir_all(&config_dir);
        unsafe {
            match previous_config {
                Some(value) => std::env::set_var("HERDR_MCP_CONFIG_DIR", value),
                None => std::env::remove_var("HERDR_MCP_CONFIG_DIR"),
            }
        }
    }

    #[test]
    fn browser_registry_private_methods_are_read_only_stable_ref_queries() {
        use crate::state_store::{
            BrowserEndpointRegistrationInput, BrowserProviderObservationInput,
            BrowserResourceObservationInput,
        };
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let (endpoint_ref, account_ref) = {
            let mut guard = store.lock().unwrap();
            let endpoint = guard
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "private-browser-profile-seed-1234",
                    browser_family: "chrome",
                    extension_version: "0.1.90",
                    observed_at: 10,
                })
                .unwrap();
            guard
                .observe_browser_provider(BrowserProviderObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    adapter_protocol_version: 1,
                    observation_generation: 7,
                    capabilities_json: r#"{"operations":["identity.inspect"]}"#,
                    observed_at: 11,
                })
                .unwrap();
            let account = guard
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "account",
                    parent_ref: None,
                    native_identity: "native-account-hidden",
                    display_label: Some("Work"),
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            (endpoint.endpoint_ref, account.resource_ref)
        };

        let listed = browser_registry_call(
            &store,
            "herdr_mcp.browser_endpoint.list",
            &json!({"limit": 4}),
        );
        assert_eq!(listed["ok"], true);
        assert_eq!(listed["endpoints"].as_array().unwrap().len(), 1);
        assert_eq!(listed["endpoints"][0]["endpoint_ref"], endpoint_ref);
        assert_eq!(listed["endpoints"][0]["consent"]["webchat_control"], true);

        let inspected = browser_registry_call(
            &store,
            "herdr_mcp.browser_endpoint.inspect",
            &json!({"endpoint_ref": endpoint_ref}),
        );
        assert_eq!(inspected["ok"], true);
        assert_eq!(inspected["provider_states"][0]["provider"], "chatgpt");
        assert_eq!(inspected["provider_states"][0]["observation_generation"], 7);
        assert_eq!(
            inspected["provider_states"][0]["capabilities"]["schema_version"],
            1
        );
        assert_eq!(
            inspected["provider_states"][0]["capabilities"]["operations"][0],
            "identity.inspect"
        );
        assert_eq!(
            inspected["provider_states"][0]["capabilities"]["input_contract"]["message"]["max_bytes"],
            262_144
        );
        assert_eq!(
            inspected["provider_states"][0]["capabilities"]["provider_dynamic_limits"]["turn_timeout_ms"]
                ["status"],
            "unknown"
        );

        let resolved = browser_registry_call(
            &store,
            "herdr_mcp.browser_resource.resolve",
            &json!({
                "endpoint_ref": endpoint_ref,
                "provider": "chatgpt",
                "kind": "account",
                "display_label": "Work",
                "expected_observation_generation": 7
            }),
        );
        assert_eq!(resolved["ok"], true);
        assert_eq!(resolved["resource"]["resource_ref"], account_ref);
        assert_eq!(resolved["resource"]["display_label"], "Work");
        assert_eq!(resolved["consent"]["webchat_control"], true);
        assert_eq!(resolved["consent"]["revision"], 0);
        assert_eq!(resolved["actuation_available"], false);
        assert!(!resolved.to_string().contains("native-account-hidden"));

        let inspected_res = browser_registry_call(
            &store,
            "herdr_mcp.browser_resource.inspect",
            &json!({"resource_ref": account_ref}),
        );
        assert_eq!(inspected_res["ok"], true);
        assert_eq!(inspected_res["resource"]["resource_ref"], account_ref);
        assert_eq!(inspected_res["consent"]["webchat_control"], true);
        assert_eq!(inspected_res["actuation_available"], false);

        let listed_res = browser_registry_call(
            &store,
            "herdr_mcp.browser_resource.list",
            &json!({"endpoint_ref": endpoint_ref}),
        );
        assert_eq!(listed_res["ok"], true);
        assert_eq!(listed_res["actuation_available"], false);
        assert_eq!(listed_res["actuation_evaluated"], false);
        assert_eq!(listed_res["actuation_reason"], "not_evaluated_by_list");

        let injected = browser_registry_call(
            &store,
            "herdr_mcp.browser_resource.resolve",
            &json!({
                "endpoint_ref": endpoint_ref,
                "provider": "chatgpt",
                "kind": "account",
                "native_identity": "attacker-controlled",
            }),
        );
        assert_eq!(injected["ok"], false);
        assert_eq!(injected["code"], "browser_registry_params_invalid");

        let device_override = browser_registry_call(
            &store,
            "herdr_mcp.browser_endpoint.list",
            &json!({"device_id": "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV"}),
        );
        assert_eq!(device_override["ok"], false);
        assert_eq!(device_override["code"], "browser_registry_params_invalid");

        let remote_consent = browser_registry_call(
            &store,
            "herdr_mcp.browser_endpoint.consent",
            &json!({"endpoint_ref": endpoint_ref, "webchat_control": true}),
        );
        assert_eq!(remote_consent["ok"], false);
        assert_eq!(remote_consent["code"], "unknown_local_method");

        let identity = contract::identity().unwrap();
        assert_eq!(identity.epoch, 5);
        assert_eq!(identity.tool_count, 18);
    }

    #[test]
    fn browser_endpoint_list_and_inspect_mark_liveness_from_extension_heartbeat() {
        use crate::state_store::BrowserEndpointRegistrationInput;
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let (live_ref, stale_ref) = {
            let mut guard = store.lock().unwrap();
            let live = guard
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "endpoint-liveness-live-profile",
                    browser_family: "chrome",
                    extension_version: "0.1.202",
                    observed_at: 200,
                })
                .unwrap();
            let stale = guard
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "endpoint-liveness-stale-profile",
                    browser_family: "chrome",
                    extension_version: "0.1.190",
                    observed_at: 5,
                })
                .unwrap();
            (live.endpoint_ref, stale.endpoint_ref)
        };

        // A small fake at the actuator boundary: it observes the same
        // heartbeat contract the real SSE broker exposes.
        struct HeartbeatActuator {
            live_endpoint_ref: String,
        }
        impl BrowserActuator for HeartbeatActuator {
            fn actuate(
                &self,
                _operation: &str,
                _params: &Value,
                _expected_generation: i64,
                _dispatch_id: Option<&str>,
            ) -> Result<BrowserPostconditionEvidence, String> {
                Err("browser_actuation_unsupported_in_liveness_test".to_owned())
            }
            fn endpoint_live(&self, endpoint_ref: &str) -> Option<bool> {
                Some(endpoint_ref == self.live_endpoint_ref)
            }
        }
        let actuator = HeartbeatActuator {
            live_endpoint_ref: live_ref.clone(),
        };

        let listed = browser_registry_call_with_liveness(
            &store,
            "herdr_mcp.browser_endpoint.list",
            &json!({}),
            Some(&actuator),
        );
        assert_eq!(listed["ok"], true);
        let endpoints = listed["endpoints"].as_array().unwrap();
        assert_eq!(endpoints.len(), 2);
        for endpoint in endpoints {
            // Backward compatibility: the historical fields stay unchanged.
            assert!(endpoint["endpoint_ref"].is_string());
            assert!(endpoint["last_observed_at"].is_i64());
            assert_eq!(endpoint["consent"]["webchat_control"], true);
            match endpoint["endpoint_ref"].as_str().unwrap() {
                value if value == live_ref => {
                    assert_eq!(endpoint["live"], true);
                    assert_eq!(endpoint["status"], "live");
                }
                value if value == stale_ref => {
                    assert_eq!(endpoint["live"], false);
                    assert_eq!(endpoint["status"], "stale");
                }
                other => panic!("unexpected endpoint in list: {other}"),
            }
        }

        let inspected = browser_registry_call_with_liveness(
            &store,
            "herdr_mcp.browser_endpoint.inspect",
            &json!({"endpoint_ref": stale_ref}),
            Some(&actuator),
        );
        assert_eq!(inspected["ok"], true);
        assert_eq!(inspected["endpoint"]["live"], false);
        assert_eq!(inspected["endpoint"]["status"], "stale");

        // Without an actuator there is no heartbeat signal at all: the
        // liveness is unknown and must not be misreported as stale.
        let unknown = browser_registry_call(&store, "herdr_mcp.browser_endpoint.list", &json!({}));
        for endpoint in unknown["endpoints"].as_array().unwrap() {
            assert!(endpoint["live"].is_null());
            assert_eq!(endpoint["status"], "unknown");
        }
    }

    #[test]
    fn browser_typed_operations_route_with_frozen_provider_neutral_inputs() {
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let endpoint_ref = format!("bep_{}", "a".repeat(64));
        let account_ref = format!("br_{}", "b".repeat(64));
        let space_ref = format!("br_{}", "c".repeat(64));
        let session_ref = format!("br_{}", "d".repeat(64));
        let dispatch_id = format!("bd_{}", "e".repeat(64));
        let cases = vec![
            (
                "herdr_mcp.browser_space.create",
                json!({
                    "endpoint_ref": endpoint_ref,
                    "provider": "chatgpt",
                    "account_ref": account_ref,
                    "display_label": "Project",
                    "expected_generation": 7,
                    "idempotency_key": "space-create-1"
                }),
            ),
            (
                "herdr_mcp.browser_space.open",
                json!({
                    "space_ref": space_ref,
                    "expected_generation": 7,
                    "idempotency_key": "space-open-1"
                }),
            ),
            (
                "herdr_mcp.browser_space.inspect",
                json!({"space_ref": space_ref}),
            ),
            (
                "herdr_mcp.browser_session.create",
                json!({
                    "endpoint_ref": endpoint_ref,
                    "provider": "chatgpt",
                    "account_ref": account_ref,
                    "space_ref": space_ref,
                    "display_label": "Conversation",
                    "expected_generation": 7,
                    "idempotency_key": "session-create-1"
                }),
            ),
            (
                "herdr_mcp.browser_session.open",
                json!({
                    "session_ref": session_ref,
                    "expected_generation": 7,
                    "idempotency_key": "session-open-1"
                }),
            ),
            (
                "herdr_mcp.browser_session.inspect",
                json!({"session_ref": session_ref}),
            ),
            (
                "herdr_mcp.browser_message.append",
                json!({
                    "session_ref": session_ref,
                    "message": "hello",
                    "expected_generation": 7,
                    "idempotency_key": "message-append-1"
                }),
            ),
            (
                "herdr_mcp.browser_composer.set_reasoning",
                json!({
                    "session_ref": session_ref,
                    "reasoning_effort": "balanced",
                    "expected_generation": 7,
                    "idempotency_key": "reasoning-1"
                }),
            ),
            (
                "herdr_mcp.browser_composer.set_apps",
                json!({
                    "session_ref": session_ref,
                    "required_apps": ["herdr"],
                    "expected_generation": 7,
                    "idempotency_key": "apps-1"
                }),
            ),
            (
                "herdr_mcp.browser_dispatch.submit",
                json!({
                    "session_ref": session_ref,
                    "message": "ship it",
                    "reasoning_effort": "thorough",
                    "required_apps": ["herdr"],
                    "expected_generation": 7,
                    "idempotency_key": "dispatch-1",
                    "work_chain_id": "wc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                    "lane_id": "lane-alpha"
                }),
            ),
            (
                "herdr_mcp.browser_dispatch.status",
                json!({"dispatch_id": dispatch_id}),
            ),
            (
                "herdr_mcp.browser_dispatch.stop",
                json!({
                    "dispatch_id": dispatch_id,
                    "expected_generation": 7,
                    "idempotency_key": "dispatch-stop-1"
                }),
            ),
        ];

        for (method, params) in cases {
            let result = browser_operation_call(&store, method, &params);
            assert_ne!(result["code"], "unknown_local_method", "{method}");
            assert_ne!(
                result["code"], "browser_operation_params_invalid",
                "{method}"
            );
            assert_ne!(result["code"], "browser_forbidden_input", "{method}");
        }
    }

    #[test]
    fn browser_typed_operations_reject_forbidden_and_provider_native_inputs() {
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let session_ref = format!("br_{}", "d".repeat(64));
        for field in [
            "selector",
            "xpath",
            "javascript",
            "cdp",
            "macro",
            "url",
            "shell",
            "bearer_token",
            "refresh_token",
            "credentials",
            "native_identity",
        ] {
            let mut params = json!({
                "session_ref": session_ref,
                "message": "safe message",
                "expected_generation": 7,
                "idempotency_key": "dispatch-forbidden-1"
            });
            params
                .as_object_mut()
                .unwrap()
                .insert(field.to_owned(), json!("attacker-controlled"));
            let result =
                browser_operation_call(&store, "herdr_mcp.browser_dispatch.submit", &params);
            assert_eq!(result["code"], "browser_forbidden_input", "{field}");
            assert_eq!(result["field"], field);
        }

        let native_reasoning = browser_operation_call(
            &store,
            "herdr_mcp.browser_composer.set_reasoning",
            &json!({
                "session_ref": session_ref,
                "reasoning_effort": "medium",
                "expected_generation": 7,
                "idempotency_key": "reasoning-native-1"
            }),
        );
        assert_eq!(native_reasoning["code"], "browser_reasoning_effort_invalid");

        let arbitrary_json = browser_operation_call(
            &store,
            "herdr_mcp.browser_dispatch.submit",
            &json!({
                "session_ref": session_ref,
                "message": "safe message",
                "expected_generation": 7,
                "idempotency_key": "dispatch-options-1",
                "options": {"anything": true}
            }),
        );
        assert_eq!(arbitrary_json["code"], "browser_operation_params_invalid");

        let oversized = browser_operation_call(
            &store,
            "herdr_mcp.browser_dispatch.submit",
            &json!({
                "session_ref": session_ref,
                "message": "x".repeat(262_145),
                "expected_generation": 7,
                "idempotency_key": "dispatch-oversized-1"
            }),
        );
        assert_eq!(oversized["code"], "browser_message_invalid");
        assert_eq!(oversized["limit"]["kind"], "max_bytes");
        assert_eq!(oversized["limit"]["max_bytes"], 262_144);
        assert_eq!(oversized["limit"]["actual_bytes"], 262_145);
    }

    #[test]
    fn browser_entrypoints_accept_multiline_messages() {
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let endpoint_ref = format!("bep_{}", "a".repeat(64));
        let account_ref = format!("br_{}", "b".repeat(64));
        let space_ref = format!("br_{}", "c".repeat(64));
        let session_ref = format!("br_{}", "d".repeat(64));
        let message = "first line\n\nsecond paragraph\twith tab\r\nthird";
        let mut outcomes = Vec::new();
        for (method, params) in [
            (
                "herdr_mcp.browser_session.create",
                json!({
                    "endpoint_ref": endpoint_ref,
                    "provider": "chatgpt",
                    "account_ref": account_ref,
                    "space_ref": space_ref,
                    "display_label": "Conversation",
                    "message": message,
                    "expected_generation": 7,
                    "idempotency_key": "session-create-multiline-1"
                }),
            ),
            (
                "herdr_mcp.browser_message.append",
                json!({
                    "session_ref": session_ref,
                    "message": message,
                    "expected_generation": 7,
                    "idempotency_key": "message-append-multiline-1"
                }),
            ),
            (
                "herdr_mcp.browser_dispatch.submit",
                json!({
                    "session_ref": session_ref,
                    "message": message,
                    "reasoning_effort": "thorough",
                    "required_apps": ["herdr"],
                    "expected_generation": 7,
                    "idempotency_key": "dispatch-multiline-1"
                }),
            ),
        ] {
            let result = browser_operation_call(&store, method, &params);
            let code = result["code"].as_str().unwrap_or("ok");
            outcomes.push(format!("{method}: {code}"));
        }
        assert!(
            !outcomes
                .iter()
                .any(|entry| entry.contains("browser_message_")),
            "multiline messages must not fail message validation: {outcomes:?}"
        );
    }

    #[test]
    fn browser_session_create_does_not_persist_a_foreign_accepted_user_ref() {
        use crate::state_store::{
            BrowserEndpointConsentInput, BrowserEndpointRegistrationInput,
            BrowserProviderObservationInput, BrowserResourceObservationInput,
        };
        use std::sync::{Arc, Mutex};

        struct ForeignConversationActuator {
            store: Arc<Mutex<StateStore>>,
        }

        impl BrowserActuator for ForeignConversationActuator {
            fn actuate(
                &self,
                operation: &str,
                _params: &Value,
                expected_generation: i64,
                dispatch_id: Option<&str>,
            ) -> Result<BrowserPostconditionEvidence, String> {
                if operation == BROWSER_SESSION_ARCHIVE_STATUS_METHOD {
                    // Late-acceptance readback is unavailable in this fixture.
                    return Err("browser_actuation_unavailable".to_owned());
                }
                assert_eq!(operation, BrowserOperation::SessionCreate.method());
                let reservation_ref = dispatch_id.unwrap().to_owned();
                let reservation = self
                    .store
                    .lock()
                    .unwrap()
                    .browser_session_reservation(&reservation_ref)
                    .unwrap()
                    .unwrap();
                let native_identity = format!("created-{reservation_ref}");
                let canonical_url = format!("https://chatgpt.com/c/{reservation_ref}");
                let mut guard = self.store.lock().unwrap();
                let session = guard
                    .observe_browser_resource(BrowserResourceObservationInput {
                        endpoint_ref: &reservation.endpoint_ref,
                        provider: &reservation.provider,
                        kind: "session",
                        parent_ref: reservation
                            .space_ref
                            .as_deref()
                            .or(Some(&reservation.account_ref)),
                        native_identity: &native_identity,
                        display_label: None,
                        observation_generation: expected_generation,
                        observed_at: 20,
                    })
                    .unwrap();
                guard
                    .upsert_browser_resource_locator(
                        &session.resource_ref,
                        &canonical_url,
                        expected_generation,
                        20,
                    )
                    .unwrap();
                guard
                    .materialize_browser_session_reservation(
                        &reservation_ref,
                        &session.resource_ref,
                        20,
                    )
                    .unwrap();
                drop(guard);
                let mut evidence =
                    BrowserPostconditionEvidence::resource_unavailable(expected_generation);
                evidence.command_accepted = true;
                evidence.browser_online = true;
                evidence.resource_available = true;
                evidence.stable_resource_ref_observed = true;
                evidence.lifecycle_observed = true;
                evidence.canonical_url_observed = true;
                evidence.accepted_message_observed = true;
                // The landed conversation's latest user turn belongs to somebody
                // else, and the reported digest says so.
                evidence.result = Some(accepted_result("another worker turn", "provider-foreign"));
                Ok(evidence)
            }
        }

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        let (endpoint_ref, account_ref) = {
            let mut guard = store.lock().unwrap();
            let endpoint = guard
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "foreign-ref-profile-seed",
                    browser_family: "chrome",
                    extension_version: "0.1.191",
                    observed_at: 10,
                })
                .unwrap();
            guard
                .observe_browser_provider(BrowserProviderObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    adapter_protocol_version: 1,
                    observation_generation: 7,
                    capabilities_json: r#"{"operations":["session.create","session.open","composer.submit"]}"#,
                    observed_at: 11,
                })
                .unwrap();
            let account = guard
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "account",
                    parent_ref: None,
                    native_identity: "foreign-ref-account",
                    display_label: None,
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            guard
                .upsert_browser_resource_locator(
                    &account.resource_ref,
                    "https://chatgpt.com",
                    7,
                    12,
                )
                .unwrap();
            guard
                .set_browser_endpoint_consent(BrowserEndpointConsentInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    expected_revision: 0,
                    webchat_control_allowed: true,
                    tool_bridge_allowed: false,
                    tool_bridge_mutation_allowed: false,
                    observed_at: 13,
                })
                .unwrap();
            (endpoint.endpoint_ref, account.resource_ref)
        };

        let actuator = ForeignConversationActuator {
            store: store.clone(),
        };
        let created = browser_operation_call_with_grant(
            &store,
            "herdr_mcp.browser_session.create",
            &json!({
                "endpoint_ref": endpoint_ref,
                "provider": "chatgpt",
                "account_ref": account_ref,
                "display_label": "Foreign conversation create",
                "message": "ship the patch",
                "expected_generation": 7,
                "idempotency_key": "session-create-foreign-ref-1"
            }),
            true,
            Some(&actuator),
        );
        assert_eq!(created["ok"], false);
        assert_eq!(created["code"], "uncertain");
        assert_eq!(created["delivery_state"], "uncertain");
        let reservation_ref = created["reservation_ref"].as_str().unwrap().to_owned();
        let stored = store
            .lock()
            .unwrap()
            .browser_session_reservation(&reservation_ref)
            .unwrap()
            .unwrap();
        assert_eq!(stored.state, "materialized");
        assert_eq!(
            stored.accepted_user_message_ref, None,
            "a create that landed on a foreign conversation must not retain its accepted user message",
        );

        // The same create replay must not promote the foreign identity either.
        let replayed = browser_operation_call_with_grant(
            &store,
            "herdr_mcp.browser_session.create",
            &json!({
                "endpoint_ref": endpoint_ref,
                "provider": "chatgpt",
                "account_ref": account_ref,
                "display_label": "Foreign conversation create",
                "message": "ship the patch",
                "expected_generation": 7,
                "idempotency_key": "session-create-foreign-ref-1"
            }),
            true,
            Some(&actuator),
        );
        assert_eq!(replayed["delivery_state"], "uncertain");
        let after_replay = store
            .lock()
            .unwrap()
            .browser_session_reservation(&reservation_ref)
            .unwrap()
            .unwrap();
        assert_eq!(after_replay.accepted_user_message_ref, None);
    }

    #[test]
    fn browser_session_create_accepts_only_the_exact_provider_text_digest() {
        let params = json!({
            "message": "ship the patch",
            "required_apps": [],
        });
        let mut evidence = BrowserPostconditionEvidence::resource_unavailable(7);
        evidence.resource_available = true;
        evidence.command_accepted = true;
        evidence.stable_resource_ref_observed = true;
        evidence.lifecycle_observed = true;
        evidence.canonical_url_observed = true;
        evidence.accepted_message_observed = true;
        // The landed conversation's latest user turn is somebody else's text.
        evidence.result = Some(accepted_result("another worker turn", "provider-user-1"));
        assert_eq!(
            browser_delivery_state_from_postcondition(
                BrowserOperation::SessionCreate,
                &params,
                7,
                &evidence,
            )
            .unwrap(),
            BrowserDeliveryState::Uncertain,
            "a foreign user turn must never materialize this create",
        );
        // The identity reader still sees the reported ref; persistence decides
        // separately whether it may be retained (see the create settlement test).
        assert_eq!(
            browser_evidence_accepted_user_message_ref(&evidence).unwrap(),
            Some("provider-user-1".to_owned()),
        );
        assert_eq!(
            browser_session_create_evidence_accepted_ref(&params, &evidence).unwrap(),
            None,
            "a mismatching digest must not be retained as the accepted user message",
        );

        evidence.result = Some(accepted_result("ship the patch", "provider-user-1"));
        assert_eq!(
            browser_delivery_state_from_postcondition(
                BrowserOperation::SessionCreate,
                &params,
                7,
                &evidence,
            )
            .unwrap(),
            BrowserDeliveryState::Applied,
        );

        // ChatGPT re-renders composer line breaks when it stores the turn; the
        // whitespace-canonical digest is still the same message.
        evidence.result = Some(accepted_result("ship the\n\npatch", "provider-user-1"));
        assert_eq!(
            browser_delivery_state_from_postcondition(
                BrowserOperation::SessionCreate,
                &params,
                7,
                &evidence,
            )
            .unwrap(),
            BrowserDeliveryState::Applied,
        );

        // A named App mention token in front of the body is stripped by the
        // content script's body digest, so the message still matches.
        let mut app_result =
            accepted_text_and_body_evidence("herdr ship the patch", "ship the patch");
        app_result.as_object_mut().unwrap().insert(
            "accepted_user_message_ref".to_owned(),
            json!("provider-user-1"),
        );
        evidence.result = Some(app_result);
        assert_eq!(
            browser_delivery_state_from_postcondition(
                BrowserOperation::SessionCreate,
                &params,
                7,
                &evidence,
            )
            .unwrap(),
            BrowserDeliveryState::Applied,
        );

        // A reported identity with no accepted-text digest is missing proof.
        evidence.result = Some(json!({"accepted_user_message_ref": "provider-user-1"}));
        assert_eq!(
            browser_delivery_state_from_postcondition(
                BrowserOperation::SessionCreate,
                &params,
                7,
                &evidence,
            )
            .unwrap(),
            BrowserDeliveryState::Uncertain,
        );

        evidence.result = Some(json!({"accepted_user_text_sha256": "not-a-digest"}));
        assert_eq!(
            browser_evidence_accepted_text_matches(&params, &evidence).unwrap_err(),
            "browser_evidence_accepted_text_invalid",
        );
    }

    #[test]
    fn browser_required_app_activation_must_be_observed_before_delivery_is_applied() {
        let mut evidence = BrowserPostconditionEvidence::resource_unavailable(7);
        evidence.browser_online = true;
        evidence.resource_available = true;
        evidence.command_accepted = true;
        evidence.stable_resource_ref_observed = true;
        evidence.lifecycle_observed = true;
        evidence.canonical_url_observed = true;
        evidence.accepted_message_observed = true;
        evidence.generation_owner = Some(7);
        evidence.generation_status_observed = true;
        evidence.result = Some(accepted_result("worker turn", "provider-user-test"));
        let requiring_app = json!({"message": "worker turn", "required_apps": ["herdr"]});
        let legacy = json!({"message": "worker turn"});

        for operation in [
            BrowserOperation::SessionCreate,
            BrowserOperation::DispatchSubmit,
        ] {
            assert_eq!(
                browser_delivery_state_from_postcondition(operation, &legacy, 7, &evidence)
                    .unwrap(),
                BrowserDeliveryState::Applied,
            );
            assert_eq!(
                browser_delivery_state_from_postcondition(operation, &requiring_app, 7, &evidence)
                    .unwrap(),
                BrowserDeliveryState::Uncertain,
            );
            evidence.required_apps_readback = vec!["other".to_owned()];
            assert_eq!(
                browser_delivery_state_from_postcondition(operation, &requiring_app, 7, &evidence)
                    .unwrap(),
                BrowserDeliveryState::Uncertain,
            );
            evidence.required_apps_readback = vec!["herdr".to_owned()];
            assert_eq!(
                browser_delivery_state_from_postcondition(operation, &requiring_app, 7, &evidence)
                    .unwrap(),
                BrowserDeliveryState::Applied,
            );
            evidence.required_apps_readback.clear();
        }
    }

