    #[test]
    fn browser_handoff_prepare_is_stable_and_reuses_existing_continuity() {
        use crate::state_store::ContinuityTurnInput;
        use std::sync::{Arc, Mutex};

        let store = Arc::new(Mutex::new(StateStore::open(":memory:").unwrap()));
        {
            let mut guard = store.lock().unwrap();
            guard
                .append_continuity_turn(ContinuityTurnInput {
                    continuity_id: "hc:canonical",
                    conversation_id: "source-conversation",
                    workspace_id: Some("w-canonical"),
                    project_id: Some("g-p-canonical"),
                    title: Some("Finish canonical handoff convergence"),
                    message_id: "canonical-user-1",
                    role: "user",
                    text: "Keep the durable journal authoritative and the handoff compact.",
                    fingerprint: None,
                    observed_at: 100,
                })
                .unwrap();
        }
        let source_url = "https://chatgpt.com/g/g-p-canonical/c/source-conversation";
        let params = json!({
            "continuity_id": "hc:canonical",
            "source_url": source_url,
            "objective": "Finish canonical handoff convergence",
            "work_chain_id": "wc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "handoff_id": "ht:canonical"
        });
        let first = browser_handoff_prepare(&store, &params);
        let second = browser_handoff_prepare(&store, &params);
        assert_eq!(first["ok"], true);
        // No browser registry entry exists for this source URL, so the canonical packet is
        // still prepared while automatic delivery scope stays explicitly unavailable.
        assert_eq!(first["source_route"], Value::Null);
        assert_eq!(
            first["source_route_error"],
            "browser_source_session_not_found"
        );
        assert_eq!(first["handoff"], second["handoff"]);
        assert_eq!(
            first["handoff"]["message"],
            first["automatic_delivery"]["params"]["message"]
        );
        assert_eq!(
            first["handoff"]["message"],
            first["manual_delivery"]["copy_prompt"]
        );
        assert_eq!(first["handoff"]["continuity_id"], "hc:canonical");
        assert_eq!(first["handoff"]["source_url"], source_url);
        assert_eq!(
            first["handoff"]["work_chain_id"],
            "wc_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
        );
        let message = first["handoff"]["message"].as_str().unwrap();
        assert!(message.contains("continuity.resume"));
        assert!(message.contains("workspace / Git / runtime"));
        assert!(message.contains("delivery/execution"));
        assert!(!message.contains("host-side pre-delivery safety rejection"));
        // ChatGPT rewrites pasted conversation URLs into chips; reference by id.
        assert!(!message.contains(source_url));
        assert!(message.contains(&browser_composer_source_reference(source_url)));
        assert!(message.len() < 2048);
        assert!(!message.contains("Keep the durable journal authoritative"));
        assert!(first.get("safety").is_none());

        let mismatched_source = browser_handoff_prepare(
            &store,
            &json!({
                "continuity_id": "hc:canonical",
                "source_url": "https://chatgpt.com/g/g-p-canonical/c/different-conversation",
            }),
        );
        assert_eq!(
            mismatched_source["code"],
            "browser_handoff_source_continuity_mismatch"
        );

        let missing = browser_handoff_prepare(
            &store,
            &json!({
                "continuity_id": "hc:missing",
                "source_url": source_url,
            }),
        );
        assert_eq!(missing["code"], "continuity_not_found");
        assert!(
            store
                .lock()
                .unwrap()
                .continuity_resume("hc:missing", 1)
                .unwrap()
                .is_none()
        );
    }

    const TEST_CONVERSATION_UUID: &str = "5d2a9c3e-1f4b-4a6d-8e2f-0b7c9d1e3a5b";

    /// user binds dispatch parents for every registered adapter | Given the
    /// WebChat adapter registry | When parent-session provider qualification
    /// is checked | Then chatgpt, claude, and grok all qualify while
    /// unregistered provider names stay refused.
    #[test]
    fn parent_session_provider_qualification_follows_adapter_registry() {
        assert!(webchat_adapter_binds_parent_session("chatgpt"));
        assert!(webchat_adapter_binds_parent_session("claude"));
        assert!(webchat_adapter_binds_parent_session("grok"));
        assert!(!webchat_adapter_binds_parent_session("z.ai"));
        assert!(!webchat_adapter_binds_parent_session(""));
    }

    /// user resolves a Grok conversation through an adapter | Given a grok.com
    /// conversation URL | When the URL identity is resolved | Then the result
    /// names the claiming adapter via the adapter registry (not a provider
    /// match arm) while the compatibility provider field stays "grok".
    #[test]
    fn conversation_url_ref_for_grok_returns_adapter_id() {
        let url = format!("https://grok.com/c/{}", TEST_CONVERSATION_UUID);
        let resolved = browser_conversation_url_ref(&url)
            .expect("registered grok URL must not error")
            .expect("grok conversation URL must resolve");
        assert_eq!(resolved.adapter_id, "grok");
        assert_eq!(resolved.provider, "grok");
        assert_eq!(
            resolved.conversation_id.to_ascii_lowercase(),
            TEST_CONVERSATION_UUID
        );
        assert_eq!(resolved.project_id, None);
    }

    /// user gets a typed refusal for unsupported hosts | Given a well-formed
    /// https URL on a host no registered adapter claims | When the URL
    /// identity is resolved | Then the result is a typed adapter_unsupported
    /// error, distinguishable from a non-conversation URL on a known host.
    #[test]
    fn conversation_url_ref_for_unknown_host() {
        let url = format!("https://example.com/c/{}", TEST_CONVERSATION_UUID);
        assert_eq!(
            browser_conversation_url_ref(&url),
            Err("adapter_unsupported")
        );
        // A known-host URL that is not a conversation URL stays Ok(None),
        // not the typed unsupported error.
        assert_eq!(
            browser_conversation_url_ref("https://grok.com/about"),
            Ok(None)
        );
    }

    /// user keeps provider compatibility while adapters claim URLs | Given
    /// chatgpt and claude conversation URLs | When resolved | Then provider,
    /// adapter_id, and identity fields match the pre-registry behaviour.
    #[test]
    fn conversation_url_ref_provider_compat_across_registry() {
        let chatgpt = browser_conversation_url_ref(&format!(
            "https://chatgpt.com/c/{}",
            TEST_CONVERSATION_UUID
        ))
        .expect("chatgpt must resolve")
        .expect("chatgpt conversation URL must resolve");
        assert_eq!(chatgpt.adapter_id, "chatgpt");
        assert_eq!(chatgpt.provider, "chatgpt");

        let claude = browser_conversation_url_ref(&format!(
            "https://claude.ai/chat/{}",
            TEST_CONVERSATION_UUID
        ))
        .expect("claude must resolve")
        .expect("claude conversation URL must resolve");
        assert_eq!(claude.adapter_id, "claude");
        assert_eq!(claude.provider, "claude");

        let grok_project = browser_conversation_url_ref(&format!(
            "https://grok.com/project/{}?chat={}",
            TEST_CONVERSATION_UUID, TEST_CONVERSATION_UUID
        ))
        .expect("grok project must resolve")
        .expect("grok project URL must resolve");
        assert_eq!(grok_project.adapter_id, "grok");
        assert_eq!(
            grok_project.project_id,
            Some(TEST_CONVERSATION_UUID.to_owned())
        );

        // Malformed and non-https inputs stay Ok(None), never the typed error.
        assert_eq!(browser_conversation_url_ref("not a url"), Ok(None));
        assert_eq!(
            browser_conversation_url_ref("http://grok.com/c/x"),
            Ok(None)
        );
    }

    #[test]
    fn user_source_route_given_one_session_when_resolved_then_exact_route_used() {
        use crate::state_store::{
            BrowserEndpointConsentInput, BrowserEndpointRegistrationInput,
            BrowserProviderObservationInput, BrowserResourceObservationInput, ContinuityTurnInput,
        };
        use std::sync::{Arc, Mutex};

        let source_url = "https://chatgpt.com/g/g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/c/source-conv";
        let mut store = StateStore::open(":memory:").unwrap();
        let (endpoint_ref, account_ref, space_ref, session_ref);
        {
            let endpoint = store
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "handoff-route-profile-seed",
                    browser_family: "chrome",
                    extension_version: "0.1.91",
                    observed_at: 10,
                })
                .unwrap();
            store
                .observe_browser_provider(BrowserProviderObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    adapter_protocol_version: 1,
                    observation_generation: 7,
                    capabilities_json: r#"{"operations":["session.create","composer.submit"]}"#,
                    observed_at: 11,
                })
                .unwrap();
            let account = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "account",
                    parent_ref: None,
                    native_identity: "handoff-route-account",
                    display_label: None,
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            let space = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "space",
                    parent_ref: Some(&account.resource_ref),
                    native_identity: "handoff-route-project",
                    display_label: Some("herdr-mcp"),
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            let session = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "session",
                    parent_ref: Some(&space.resource_ref),
                    native_identity: "handoff-route-source",
                    display_label: Some("Source"),
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            store
                .upsert_browser_resource_locator(&session.resource_ref, source_url, 7, 12)
                .unwrap();
            store
                .set_browser_endpoint_consent(BrowserEndpointConsentInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    expected_revision: 0,
                    webchat_control_allowed: true,
                    tool_bridge_allowed: false,
                    tool_bridge_mutation_allowed: false,
                    observed_at: 13,
                })
                .unwrap();
            store
                .append_continuity_turn(ContinuityTurnInput {
                    continuity_id: "hc:routed",
                    conversation_id: "source-conv",
                    workspace_id: Some("w-routed"),
                    project_id: Some("g-p-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
                    title: Some("Routed handoff"),
                    message_id: "routed-user-1",
                    role: "user",
                    text: "route this canonical handoff",
                    fingerprint: None,
                    observed_at: 100,
                })
                .unwrap();
            endpoint_ref = endpoint.endpoint_ref;
            account_ref = account.resource_ref;
            space_ref = space.resource_ref;
            session_ref = session.resource_ref;
        }
        let store = Arc::new(Mutex::new(store));
        let prepared = browser_handoff_prepare(
            &store,
            &json!({"continuity_id": "hc:routed", "source_url": source_url}),
        );
        assert_eq!(prepared["ok"], true);
        assert_eq!(prepared["source_route_error"], Value::Null);
        assert_eq!(prepared["source_route"]["session_ref"], session_ref);
        assert_eq!(prepared["source_route"]["provider"], "chatgpt");
        assert_eq!(prepared["source_route"]["endpoint_ref"], endpoint_ref);
        assert_eq!(prepared["source_route"]["account_ref"], account_ref);
        assert_eq!(prepared["source_route"]["space_ref"], space_ref);
        assert_eq!(prepared["source_route"]["expected_generation"], 7);
        assert_eq!(prepared["source_route"]["display_label"], "herdr-mcp");
        assert_eq!(
            prepared["handoff"]["message"],
            prepared["manual_delivery"]["copy_prompt"]
        );
        assert_eq!(
            prepared["handoff"]["message"],
            prepared["automatic_delivery"]["params"]["message"]
        );
        assert_eq!(
            prepared["automatic_delivery"]["params"]["source_url"],
            source_url
        );
        // The source-anchored create must derive exactly the same scope from the same URL,
        // because both callers share one route resolution.
        let (create_params, create_source_session_ref) = browser_session_create_params_from_source(
            &store.lock().unwrap(),
            &json!({
                "source_url": source_url,
                "message": "continue from the canonical packet",
                "idempotency_key": "handoff-route-1"
            }),
        )
        .unwrap()
        .unwrap();
        assert_eq!(create_source_session_ref, session_ref);
        assert_eq!(create_params["endpoint_ref"], endpoint_ref);
        assert_eq!(create_params["account_ref"], account_ref);
        assert_eq!(create_params["space_ref"], space_ref);
        assert_eq!(create_params["expected_generation"], 7);
        assert_eq!(create_params["display_label"], "herdr-mcp");
        assert_eq!(create_params["provider"], "chatgpt");
        assert_eq!(create_params.get("required_apps"), None);
        let (with_app, same_source) = browser_session_create_params_from_source(
            &store.lock().unwrap(),
            &json!({
                "source_url": source_url,
                "message": "read-only tool activation",
                "idempotency_key": "handoff-route-app-1",
                "required_apps": ["herdr"]
            }),
        )
        .unwrap()
        .unwrap();
        assert_eq!(same_source, session_ref);
        assert_eq!(with_app["required_apps"], json!(["herdr"]));
        let duplicate_app = browser_session_create_params_from_source(
            &store.lock().unwrap(),
            &json!({
                "source_url": source_url,
                "message": "not dispatched",
                "idempotency_key": "handoff-route-app-2",
                "required_apps": ["herdr", "herdr"]
            }),
        )
        .unwrap_err();
        assert_eq!(duplicate_app["code"], "browser_required_apps_invalid");
    }

    /// user owner | Given a session registered under the canonical project URL
    /// | When the equivalent vanity URL variant (display-name suffix) is used
    /// | Then the same session route is resolved; unrelated and malformed URLs
    /// still fail closed.
    #[test]
    fn user_source_route_given_vanity_url_variant_when_resolved_then_same_session_as_canonical() {
        use crate::state_store::{
            BrowserEndpointRegistrationInput, BrowserProviderObservationInput,
            BrowserResourceObservationInput,
        };
        use std::sync::{Arc, Mutex};

        const CANONICAL: &str = "https://chatgpt.com/g/g-p-6a89c078669481918c8eb70fdfd3d978/c/6ace54d2-4fbc-83e9-8c9f-b99360c5b44f";
        const VANITY: &str = "https://chatgpt.com/g/g-p-6a89c078669481918c8eb70fdfd3d978-herdr-mcp/c/6ace54d2-4fbc-83e9-8c9f-b99360c5b44f";

        let mut store = StateStore::open(":memory:").unwrap();
        let (endpoint_ref, account_ref, session_ref);
        {
            let endpoint = store
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "vanity-route-profile-seed",
                    browser_family: "chrome",
                    extension_version: "0.1.212",
                    observed_at: 10,
                })
                .unwrap();
            store
                .observe_browser_provider(BrowserProviderObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    adapter_protocol_version: 1,
                    observation_generation: 7,
                    capabilities_json: r#"{"operations":["session.create"]}"#,
                    observed_at: 11,
                })
                .unwrap();
            let account = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "account",
                    parent_ref: None,
                    native_identity: "vanity-route-account",
                    display_label: None,
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            let session = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "session",
                    parent_ref: Some(&account.resource_ref),
                    native_identity: "vanity-route-session",
                    display_label: None,
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            store
                .upsert_browser_resource_locator(&session.resource_ref, CANONICAL, 7, 12)
                .unwrap();
            endpoint_ref = endpoint.endpoint_ref;
            account_ref = account.resource_ref;
            session_ref = session.resource_ref;
        }
        let store = Arc::new(Mutex::new(store));

        // Vanity URL resolves to the same registered session.
        let vanity = browser_source_resolve(&store, &json!({"source_url": VANITY}), true);
        assert_eq!(vanity["ok"], true, "{vanity}");
        assert_eq!(vanity["route"]["session_ref"], session_ref);
        assert_eq!(vanity["route"]["endpoint_ref"], endpoint_ref);
        assert_eq!(vanity["route"]["account_ref"], account_ref);

        // Canonical URL still resolves identically (no regression).
        let canonical = browser_source_resolve(&store, &json!({"source_url": CANONICAL}), true);
        assert_eq!(canonical["ok"], true);
        assert_eq!(canonical["route"]["session_ref"], session_ref);

        // Unrelated conversation URL does not route.
        let unrelated = browser_source_resolve(
            &store,
            &json!({"source_url": "https://chatgpt.com/c/unrelated-conversation-id"}),
            true,
        );
        assert_eq!(unrelated["code"], "browser_source_session_not_found");

        // Malformed URL fails at parse, not at lookup.
        let malformed = browser_source_resolve(&store, &json!({"source_url": "not-a-url"}), true);
        assert_eq!(malformed["code"], "browser_source_url_invalid");

        // Non-chatgpt origin does not route.
        let foreign = browser_source_resolve(
            &store,
            &json!({"source_url": "https://claude.ai/c/some-conversation"}),
            true,
        );
        assert_eq!(foreign["code"], "browser_source_url_invalid");
    }

    /// user owner | Given a source URL with credentials or a custom port
    /// | When browser_source_route runs | Then the URL is rejected as invalid
    /// before any locator lookup; a harmless query/fragment still routes.
    #[test]
    fn user_source_route_rejects_userinfo_and_custom_port() {
        use crate::state_store::{
            BrowserEndpointRegistrationInput, BrowserProviderObservationInput,
            BrowserResourceObservationInput,
        };
        let mut store = StateStore::open(":memory:").unwrap();
        let (endpoint_ref, _account_ref, session_ref);
        {
            let endpoint = store
                .register_browser_endpoint(BrowserEndpointRegistrationInput {
                    device_id: "dev_01ARZ3NDEKTSV4RRFFQ69G5FAV",
                    profile_seed: "port-reject-profile-seed",
                    browser_family: "chrome",
                    extension_version: "0.1.212",
                    observed_at: 10,
                })
                .unwrap();
            store
                .observe_browser_provider(BrowserProviderObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    adapter_protocol_version: 1,
                    observation_generation: 7,
                    capabilities_json: r#"{"operations":["session.create"]}"#,
                    observed_at: 11,
                })
                .unwrap();
            let account = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "account",
                    parent_ref: None,
                    native_identity: "port-reject-account",
                    display_label: None,
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            let session = store
                .observe_browser_resource(BrowserResourceObservationInput {
                    endpoint_ref: &endpoint.endpoint_ref,
                    provider: "chatgpt",
                    kind: "session",
                    parent_ref: Some(&account.resource_ref),
                    native_identity: "port-reject-session",
                    display_label: None,
                    observation_generation: 7,
                    observed_at: 12,
                })
                .unwrap();
            const CANONICAL: &str = "https://chatgpt.com/c/port-reject-conv";
            store
                .upsert_browser_resource_locator(&session.resource_ref, CANONICAL, 7, 12)
                .unwrap();
            endpoint_ref = endpoint.endpoint_ref;
            _account_ref = account.resource_ref;
            session_ref = session.resource_ref;
        }
        // Userinfo URLs are rejected before lookup.
        let userinfo = browser_source_route(
            &store,
            "https://user:pass@chatgpt.com/c/port-reject-conv",
            None,
        );
        assert_eq!(
            userinfo.err(),
            Some("browser_source_url_invalid".to_owned())
        );

        // Custom port URLs are rejected.
        let port =
            browser_source_route(&store, "https://chatgpt.com:8443/c/port-reject-conv", None);
        assert_eq!(port.err(), Some("browser_source_url_invalid".to_owned()));

        // Harmless query/fragment still routes to the same session.
        let query = browser_source_route(
            &store,
            "https://chatgpt.com/c/port-reject-conv?ref=share",
            None,
        )
        .unwrap();
        assert_eq!(query.session_ref, session_ref);
        assert_eq!(query.endpoint_ref, endpoint_ref);
    }

    /// user owner | Given a source_session_ref exceeding 96 chars
